// @ts-nocheck
export const BlogCommentsView = {
  delimiters: ['[[', ']]'],
  template: { el: '#tpl-byt3lab-blog-comments' },

  data() {
    return {
      statusFilter: '',
    };
  },

  computed: {
    comments() {
      return this.$store.state.blogComments || [];
    },
    loading() {
      return this.$store.state.loading;
    },
    userPerms() {
      return window.__BYT3LAB_PERMS__ || { read: true, write: false, publish: false, delete: false, settings: false, admin: false };
    },
  },

  mounted() {
    this.$store.dispatch('fetchBlogComments', this.statusFilter);
  },

  methods: {
    setFilter(status) {
      this.statusFilter = status;
      this.$store.dispatch('fetchBlogComments', status);
    },
    setStatus(id, status) {
      this.$store.dispatch('updateBlogCommentStatus', { id, status, filter: this.statusFilter });
    },
    removeComment(id) {
      if (confirm('Supprimer définitivement ce commentaire ?')) {
        this.$store.dispatch('deleteBlogComment', { id, filter: this.statusFilter });
      }
    },
    goBack() {
      this.$router.push('/posts');
    },
  },
};
